#ifndef WS_BLOCK_DEQUE_H
#define WS_BLOCK_DEQUE_H

#include <deque>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <optional>
#include <chrono>
#include <cassert>

namespace ws {

template <typename T>
class BlockDeque {
public:
    BlockDeque(std::size_t capacity) : capacity_(capacity), closed_(false) {
        assert(capacity > 0);
    }

    ~BlockDeque() {}

    void Clear() {
        std::lock_guard<std::mutex> lock(mtx_);
        ClearNoLock();
    }

    bool Empty() const noexcept {
        std::lock_guard<std::mutex> lock(mtx_);
        return deq_.empty();
    }

    bool Full() const noexcept {
        std::lock_guard<std::mutex> lock(mtx_);
        return deq_.size() == capacity_;
    }

    std::size_t Size() const noexcept {
        std::lock_guard<std::mutex> lock(mtx_);
        return deq_.size();
    }

    std::size_t Capacity() const noexcept {
        return capacity_;
    }

    void PushBack(T item) {
        std::lock_guard<std::mutex> lock(mtx_);
        deq_.push_back(item);
        producer_cond_.notify_one();
    }

    void PushFront(T item) {
        std::lock_guard<std::mutex> lock(mtx_);
        deq_.push_front(item);
        producer_cond_.notify_one();
    }

    const T& Front() const noexcept {
        std::lock_guard<std::mutex> lock(mtx_);
        return deq_.front();
    }

    const T& Back() const noexcept {
        std::lock_guard<std::mutex> lock(mtx_);
        return deq_.back();
    }

    T& Front() noexcept {
        std::lock_guard<std::mutex> lock(mtx_);
        return deq_.front();
    }

    T& Back() noexcept {
        std::lock_guard<std::mutex> lock(mtx_);
        return deq_.back();
    }

    std::optional<T> Pop(std::optional<std::chrono::steady_clock::duration> time_out) {
        std::unique_lock<std::mutex> locker(mtx_);
        if (deq_.empty() && closed_) {
            return std::nullopt;
        }

        if (time_out.has_value()) {
            if (!consumer_cond_.wait_for(locker, time_out.value(), [this] { return !deq_.empty() || closed_; })) {
                return std::nullopt;
            }
        } else {
            consumer_cond_.wait(locker, [this] { return !deq_.empty() || closed_; });
        }

        if (deq_.empty() && closed_) {
            return std::nullopt;
        }

        T item = deq_.front();
        deq_.pop_front();
        producer_cond_.notify_one();
        return item;
    }

    void Flush() {
        std::lock_guard<std::mutex> lock(mtx_);
        while (!deq_.empty()) {
            deq_.pop_front();
        }
    }

    void Close() {
        std::lock_guard<std::mutex> lock(mtx_);
        closed_ = true;
        ClearNoLock();
        consumer_cond_.notify_all();
        producer_cond_.notify_all();
    }

private:
    void WaitForSpace(std::unique_lock<std::mutex>& locker) {
        locker.unlock();
        producer_cond_.wait(locker, [this] { return deq_.size() < capacity_; });
        locker.lock();
    }

    void ClearNoLock() {
        while (!deq_.empty()) {
            deq_.pop_front();
        }
    }

    std::mutex mtx_;
    std::atomic_bool closed_;
    std::size_t capacity_;
    std::deque<T> deq_;
    std::condition_variable consumer_cond_;
    std::condition_variable producer_cond_;
};
}
#endif
